#pragma once
#define BATTERIES_SEQ_MUTEX_HPP

#include <batteries/async/task.hpp>
#include <batteries/int_types.hpp>
#include <batteries/null_lock.hpp>

#include <atomic>

namespace batt {

template <typename IntT>
class SeqMutex
{
   public:
    using Self = SeqMutex;

    static constexpr IntT kLockedMask = 1;

    static constexpr bool is_locked_state(IntT state) noexcept
    {
        return (state & Self::kLockedMask) != 0;
    }

    //+++++++++++-+-+--+----- --- -- -  -  -   -

    class WriteLock;

    class ReadLock
    {
        friend class WriteLock;

       public:
        explicit ReadLock(SeqMutex& mutex) noexcept : state_{mutex.state_}, before_state_{this->state_.load()}
        {
            while (Self::is_locked_state(this->before_state_)) {
                Task::yield();
                this->before_state_ = this->state_.load();
            }
        }

        //----- --- -- -  -  -   -

        [[nodiscard]] bool changed()
        {
            return this->state_.load() != this->before_state_;
        }

        //----- --- -- -  -  -   -
       private:
        std::atomic<IntT>& state_;
        IntT before_state_;
    };

    //+++++++++++-+-+--+----- --- -- -  -  -   -

    using NullLock = ::batt::NullLock;

    //+++++++++++-+-+--+----- --- -- -  -  -   -

    class WriteLock
    {
       public:
        explicit WriteLock(SeqMutex& mutex) noexcept
            : state_{mutex.state_}
            , observed_state_{this->state_.load()}
        {
            for (;;) {
                if (Self::is_locked_state(this->observed_state_)) {
                    Task::yield();
                    this->observed_state_ = this->state_.load();
                    continue;
                }
                this->observed_state_ = this->state_.fetch_or(Self::kLockedMask);
                if (Self::is_locked_state(this->observed_state_)) {
                    Task::yield();
                    this->observed_state_ = this->state_.load();
                    continue;
                }
                return;
            }
        }

        ~WriteLock() noexcept
        {
            this->state_.fetch_add(Self::kLockedMask);
        }

        //----- --- -- -  -  -   -

        bool changed_since(const ReadLock& read_lock) const noexcept
        {
            return this->observed_state_ != read_lock.before_state_;
        }

        //----- --- -- -  -  -   -
       private:
        std::atomic<IntT>& state_;
        IntT observed_state_;
    };

    //+++++++++++-+-+--+----- --- -- -  -  -   -

    SeqMutex() noexcept : state_{0}
    {
    }

    SeqMutex(const SeqMutex&) = delete;
    SeqMutex& operator=(const SeqMutex&) = delete;

    //+++++++++++-+-+--+----- --- -- -  -  -   -
   private:
    std::atomic<IntT> state_;
};

}  // namespace batt
